# Let's figure out the edge index mapping
# For K_12, edges in lexicographic order of (i,j) for i<j
# Index = sum_{k=0}^{i-1} (12-1-k) + (j-i-1)
# Or simpler: index = i*(2*12-i-1)//2 + (j-i-1)

def edge_index(i, j):
    # i < j, vertices 0..11
    return i*(2*12-i-1)//2 + (j-i-1)

# Let's list all edges
edges = []
for i in range(12):
    for j in range(i+1, 12):
        edges.append((i,j))

print(f"Total edges: {len(edges)}")
for idx, (i,j) in enumerate(edges):
    print(f"c[{idx}] = edge ({i},{j})")

# Now let's find which edges correspond to the fixed assignments
fixed = {7:0, 9:0, 23:1, 27:0, 28:0, 29:0, 33:1, 34:0, 39:1, 40:0, 53:0, 58:0, 63:0}
print("\nFixed assignments:")
for idx, val in sorted(fixed.items()):
    i,j = edges[idx]
    print(f"c[{idx}] = {val} -> edge ({i},{j})")

